def image(path,caption):
    b=path.read_bytes()
    mime='image/jpeg' if b.startswith(b'\xff\xd8') else 'image/svg+xml' if path.suffix=='.svg' else 'image/png'
    assets[str(path)]={'sha256':hashlib.sha256(b).hexdigest(),'mime':mime}
    return '<figure><figcaption>'+esc(caption)+'</figcaption><img loading="lazy" alt="'+esc(caption,quote=True)+'" src="data:'+mime+';base64,'+base64.b64encode(b).decode()+'"></figure>'
def ref(name):return C/(name+'-reference.svg')
